<?php
namespace App\Http\Controllers;
use App\Models\User;
use App\Services\{Documents,Settings};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Http\Request;
class ExportController extends Controller {
 public function download(Request $r,string $type,string $id,string $format){abort_unless(in_array($type,['resume','letter'])&&in_array($format,['pdf','docx','print']),404);$table=$type==='resume'?'resume_drafts':'cover_letter_drafts';$row=DB::table($table)->where('owner_id',$r->user()->id)->where('id',$id)->first();abort_unless($row,404);$d=json_decode($row->content_json,true);$access=Settings::access($r->user()->id);$gift=$type==='resume'&&(int)DB::table('referral_rewards')->where('owner_id',$r->user()->id)->sum('exports_remaining')>0;$watermark=!($access['paid']||$gift);$clean=$r->boolean('clean');if($clean){if(!($access['paid']||$gift)){\App\Services\MailAutomation::queue($r->user(),'download_locked',now()->toDateString());abort(402,'Clean downloads need an active plan. Open Billing to choose one.');}}else $watermark=true;
 // Generate before consuming a credit; all renderer input is structured and escaped.
 if($format==='print'){$bytes=view('document-print',['data'=>$d,'type'=>$type,'watermark'=>$watermark,'watermarkText'=>Settings::get('features')['watermarkText']])->render();$mime='text/html; charset=UTF-8';}elseif($format==='pdf'){abort_if(preg_match('/[\x{0900}-\x{09FF}]/u',json_encode($d,JSON_UNESCAPED_UNICODE))||in_array($d['documentLanguage']??'en',['hi','bn']),422,'CVTara currently supports English-language documents. Remove non-English characters to download a PDF.');$options=new \Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->set('chroot',storage_path());$pdf=new \Dompdf\Dompdf($options);$pdf->loadHtml(Documents::html($d,$type,$watermark));$pdf->setPaper('A4');$pdf->render();$bytes=$pdf->output();$mime='application/pdf';}else{$word=Documents::word($d,$type,$watermark);$file=tempnam(storage_path('app'),'doc');try{\PhpOffice\PhpWord\IOFactory::createWriter($word,'Word2007')->save($file);$bytes=file_get_contents($file);}finally{@unlink($file);}$mime='application/vnd.openxmlformats-officedocument.wordprocessingml.document';}
 if($clean)DB::transaction(function()use($r,$id,$format,$type){$uid=$r->user()->id;User::whereKey($uid)->lockForUpdate()->first();$a=Settings::access($uid);$reward=$type==='resume'?DB::table('referral_rewards')->where('owner_id',$uid)->where('exports_remaining','>',0)->lockForUpdate()->first():null;if($reward){DB::table('referral_rewards')->where('id',$reward->id)->decrement('exports_remaining');Settings::audit($uid,'reward_exported',$id);return;}abort_unless($a['paid'],402);$n=DB::table('product_usage')->where('owner_id',$uid)->where('action','export')->where('reference','like',$a['purchase']->id.':%')->count();DB::table('product_usage')->insert(['id'=>(string)Str::uuid(),'owner_id'=>$uid,'action'=>'export','reference'=>$a['purchase']->id.':'.$id.':'.$format,'created_at'=>now(),'updated_at'=>now()]);Settings::audit($uid,'document_exported',$id);});
 return response($bytes,200,['Content-Type'=>$mime,'Content-Disposition'=>'attachment; filename="CVTara-'.$type.'.'.$format.'"','Cache-Control'=>'private, no-store']);
 }
}
